-- GasGrid core tables (Oracle SQL)
CREATE TABLE users (user_id NUMBER PRIMARY KEY, name VARCHAR2(100) NOT NULL, phone VARCHAR2(10) NOT NULL, password_hash VARCHAR2(255) NOT NULL, role VARCHAR2(10) NOT NULL, address VARCHAR2(250) NOT NULL, account_status VARCHAR2(12) DEFAULT 'Active' NOT NULL, created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE orders (order_id NUMBER PRIMARY KEY, user_id NUMBER NOT NULL, cylinder_type VARCHAR2(15) NOT NULL, quantity NUMBER NOT NULL, unit_price NUMBER(10,2) NOT NULL, total_amount NUMBER(10,2) NOT NULL, priority NUMBER DEFAULT 2 NOT NULL, status VARCHAR2(25) DEFAULT 'Pending' NOT NULL, delivery_address VARCHAR2(250) NOT NULL, created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE complaints (complaint_id NUMBER PRIMARY KEY, user_id NUMBER NOT NULL, category VARCHAR2(30) NOT NULL, details VARCHAR2(500) NOT NULL, status VARCHAR2(20) DEFAULT 'Open' NOT NULL, created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE inventory (item_id NUMBER PRIMARY KEY, item_name VARCHAR2(100) NOT NULL, category VARCHAR2(20) NOT NULL, available NUMBER NOT NULL, unit VARCHAR2(20) NOT NULL);
CREATE TABLE process_logs (log_id NUMBER PRIMARY KEY, order_id NUMBER NOT NULL, pid VARCHAR2(20) NOT NULL, algorithm VARCHAR2(20) NOT NULL, waiting_time NUMBER NOT NULL, turnaround_time NUMBER NOT NULL, created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
